# -*- coding: utf-8 -*-r"""UDP 十六进制报文发送小工具规则：1. #...# 之间为注释，发送前删除。2. {} 内为变化十六进制，按字节数决定范围。   例：{22} -> 0~255       {14 24} -> 0~65535   可选择随机变化 / 自增。3. [] 内为实时时间戳，默认 Unix 秒，大端，字节数按 [] 内字节数。   例：[65 2F 4E AD]   末尾加 R 表示反转字节序：       [6A D8 AE 9C R]4. 配置记忆使用 Windows 注册表：   HKEY_CURRENT_USER\Software\UdpHexSender   不生成配置文件。"""import tkinter as tkfrom tkinter import ttk, messageboximport socketimport threadingimport timeimport randomREG_PATH = r"Software\UdpHexSender"try:    import winregexcept ImportError:    winreg = None# ---------------- 报文解析 ----------------HEX_CHARS = set("0123456789abcdefABCDEF")def strip_comments(text: str) -> str: """ 删除 #...# 注释。 处理规则： 1. 先做行内预处理：把 "# #"、"#  #" 这类连续 # 合并为单个 #，    以兼容原文中 "00 # #本端雷达状态字#" 这种写法。 2. 再逐行扫描：遇到 # 切换注释状态，注释状态内的字符全部丢弃。 3. 行尾仍在注释状态时，说明注释到行尾结束，正常结`束。 """ import re # 行内合并 "# #" -> "#"，不影响跨行注释 text = re.sub(r"#[ \t]*#", "#", text) out_lines = [] for line in text.splitlines():  in_comment = False  keep = []  for ch in line:   if ch == "#":    in_comment = not in_comment    continue   if not in_comment:    keep.append(ch)  out_lines.append("".join(keep)) return "\n".join(out_lines)def parse_hex_tokens(text: str):    """    从文本中提取连续十六进制字符片段。    例如：        "00 00 2B52" -> ["00", "00", "2B52"]        "0034"      -> ["0034"]    单个十六进制字符会被忽略，用于容忍注释删除后残留的英文字母/数字。    """    tokens = []    cur = []    def flush():        nonlocal cur        if not cur:            return        tok = "".join(cur)        cur = []        if len(tok) == 1:            # 忽略单个十六进制字符，通常是残留文本，如 SDU 中的 D、方向 2 等            return        if len(tok) % 2 != 0:            raise ValueError(f"十六进制字符数不是偶数: {tok}")        tokens.append(tok)    for ch in text:        if ch in HEX_CHARS:            cur.append(ch)        else:            flush()    flush()    return tokensdef hex_tokens_to_bytes(tokens):    out = bytearray()    for tok in tokens:        for i in range(0, len(tok), 2):            out.append(int(tok[i:i + 2], 16))    return bytes(out)def count_bytes_from_content(content: str) -> int:    tokens = parse_hex_tokens(content)    return sum(len(t) // 2 for t in tokens)def compile_template(template: str):    """    编译模板为 parts：        ('fixed', bytes)        ('var', n_bytes, var_index)        ('ts', n_bytes, reverse)    """    text = strip_comments(template)    parts = []    var_idx = 0    i = 0    while i < len(text):        ch = text[i]        if ch == "{":            j = text.find("}", i + 1)            if j < 0:                raise ValueError("未找到匹配的 }")            content = text[i + 1:j]            n = count_bytes_from_content(content)            if n <= 0:                raise ValueError("{} 内没有有效的十六进制字节")            parts.append(("var", n, var_idx))            var_idx += 1            i = j + 1        elif ch == "[":            j = text.find("]", i + 1)            if j < 0:                raise ValueError("未找到匹配的 ]")            content = text[i + 1:j].strip()            reverse = False            if content and content[-1] in ("R", "r"):                reverse = True                content = content[:-1].strip()            n = count_bytes_from_content(content)            if n <= 0:                n = 4  # 默认 4 字节时间戳            parts.append(("ts", n, reverse))            i = j + 1        else:            j = i            while j < len(text) and text[j] not in "{[":                j += 1            fixed_text = text[i:j]            tokens = parse_hex_tokens(fixed_text)            b = hex_tokens_to_bytes(tokens)            if b:                parts.append(("fixed", b))            i = j    return partsdef build_payload(parts, mode: str, counters: dict) -> bytes:    """    mode: random / inc    counters: 自增计数器，按占位符顺序保存    """    out = bytearray()    for part in parts:        kind = part[0]        if kind == "fixed":            out.extend(part[1])        elif kind == "var":            _, n, idx = part            maxv = (1 << (8 * n)) - 1            if mode == "random":                v = random.randint(0, maxv)            else:                v = counters.get(idx, 0)                counters[idx] = (v + 1) % (maxv + 1)            out.extend(v.to_bytes(n, "big"))        elif kind == "ts":            _, n, reverse = part            v = int(time.time())            maxv = (1 << (8 * n)) - 1            v &= maxv            b = v.to_bytes(n, "big")            if reverse:                b = b[::-1]            out.extend(b)    return bytes(out)# ---------------- 主界面 ----------------class UdpHexSenderApp:    def __init__(self, root):        self.root = root        self.root.title("UDP 十六进制报文发送工具")        self.root.geometry("980x760")        self.thread = None        self.stop_event = threading.Event()        self.counters = {}        self.sent_count = 0        self.var_local_ip = tk.StringVar(value="0.0.0.0")        self.var_local_port = tk.StringVar(value="0")        self.var_target_ip = tk.StringVar(value="127.0.0.1")        self.var_target_port = tk.StringVar(value="9000")        self.var_interval = tk.StringVar(value="1000")        self.var_continuous = tk.BooleanVar(value=False)        self.var_mode = tk.StringVar(value="random")        self.status_var = tk.StringVar(value="就绪")        self.build_ui()        self.load_settings()        self.root.protocol("WM_DELETE_WINDOW", self.on_close)    def build_ui(self):        main = ttk.Frame(self.root, padding=8)        main.pack(fill="both", expand=True)        cfg = ttk.LabelFrame(main, text="UDP 配置")        cfg.pack(fill="x")        # 第一行        ttk.Label(cfg, text="本机 IP").grid(row=0, column=0, sticky="w", padx=4, pady=4)        ttk.Entry(cfg, textvariable=self.var_local_ip, width=18).grid(row=0, column=1, padx=4, pady=4)        ttk.Label(cfg, text="本机端口").grid(row=0, column=2, sticky="w", padx=4, pady=4)        ttk.Entry(cfg, textvariable=self.var_local_port, width=10).grid(row=0, column=3, padx=4, pady=4)        ttk.Label(cfg, text="目标 IP").grid(row=0, column=4, sticky="w", padx=4, pady=4)        ttk.Entry(cfg, textvariable=self.var_target_ip, width=18).grid(row=0, column=5, padx=4, pady=4)        ttk.Label(cfg, text="目标端口").grid(row=0, column=6, sticky="w", padx=4, pady=4)        ttk.Entry(cfg, textvariable=self.var_target_port, width=10).grid(row=0, column=7, padx=4, pady=4)        # 第二行        ttk.Label(cfg, text="发送间隔(ms)").grid(row=1, column=0, sticky="w", padx=4, pady=4)        ttk.Entry(cfg, textvariable=self.var_interval, width=10).grid(row=1, column=1, padx=4, pady=4)        ttk.Label(cfg, text="{} 变化方式").grid(row=1, column=2, sticky="w", padx=4, pady=4)        ttk.Radiobutton(cfg, text="随机", variable=self.var_mode, value="random").grid(            row=1, column=3, sticky="w", padx=4, pady=4        )        ttk.Radiobutton(cfg, text="自增", variable=self.var_mode, value="inc").grid(            row=1, column=4, sticky="w", padx=4, pady=4        )        ttk.Checkbutton(cfg, text="持续发送", variable=self.var_continuous).grid(            row=1, column=5, sticky="w", padx=4, pady=4        )        # 报文模板        tf = ttk.LabelFrame(            main,            text="报文模板： #...# 为注释； {..} 为变化值； [..] 为时间戳； [.. R] 为反转时间戳"        )        tf.pack(fill="both", expand=True, pady=6)        self.txt_template = tk.Text(tf, height=22, wrap="none", font=("Consolas", 10))        yscroll = ttk.Scrollbar(tf, orient="vertical", command=self.txt_template.yview)        xscroll = ttk.Scrollbar(tf, orient="horizontal", command=self.txt_template.xview)        self.txt_template.configure(yscrollcommand=yscroll.set, xscrollcommand=xscroll.set)        self.txt_template.grid(row=0, column=0, sticky="nsew")        yscroll.grid(row=0, column=1, sticky="ns")        xscroll.grid(row=1, column=0, sticky="ew")        tf.rowconfigure(0, weight=1)        tf.columnconfigure(0, weight=1)        # 按钮        bf = ttk.Frame(main)        bf.pack(fill="x", pady=4)        self.btn_send = ttk.Button(bf, text="发送", command=self.on_send)        self.btn_send.pack(side="left")        ttk.Button(bf, text="清空日志", command=self.clear_log).pack(side="left", padx=6)        ttk.Label(bf, textvariable=self.status_var).pack(side="right")        # 日志        lf = ttk.LabelFrame(main, text="日志")        lf.pack(fill="both", expand=False, pady=6)        self.txt_log = tk.Text(lf, height=7, wrap="word", font=("Consolas", 9))        log_scroll = ttk.Scrollbar(lf, orient="vertical", command=self.txt_log.yview)        self.txt_log.configure(yscrollcommand=log_scroll.set)        self.txt_log.pack(side="left", fill="both", expand=True)        log_scroll.pack(side="right", fill="y")    # ---------------- 配置记忆 ----------------    def load_settings(self):        if winreg is None:            return        try:            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, REG_PATH)        except OSError:            return        def get_val(name, default):            try:                return winreg.QueryValueEx(key, name)[0]            except OSError:                return default        try:            self.var_local_ip.set(get_val("local_ip", "0.0.0.0"))            self.var_local_port.set(get_val("local_port", "0"))            self.var_target_ip.set(get_val("target_ip", "127.0.0.1"))            self.var_target_port.set(get_val("target_port", "9000"))            self.var_interval.set(get_val("interval", "1000"))            self.var_continuous.set(get_val("continuous", "0") == "1")            self.var_mode.set(get_val("mode", "random"))            template = get_val("template", "")            if template:                self.txt_template.insert("1.0", template)        finally:            winreg.CloseKey(key)    def save_settings(self):        if winreg is None:            return        try:            key = winreg.CreateKey(winreg.HKEY_CURRENT_USER, REG_PATH)            values = {                "local_ip": self.var_local_ip.get().strip(),                "local_port": self.var_local_port.get().strip(),                "target_ip": self.var_target_ip.get().strip(),                "target_port": self.var_target_port.get().strip(),                "interval": self.var_interval.get().strip(),                "continuous": "1" if self.var_continuous.get() else "0",                "mode": self.var_mode.get(),                "template": self.txt_template.get("1.0", "end-1c"),            }            for k, v in values.items():                winreg.SetValueEx(key, k, 0, winreg.REG_SZ, str(v))            winreg.CloseKey(key)        except Exception:            pass    # ---------------- 发送逻辑 ----------------    def get_net_config(self):        local_ip = self.var_local_ip.get().strip() or "0.0.0.0"        try:            local_port = int(self.var_local_port.get().strip() or "0")        except ValueError:            raise ValueError("本机端口必须是整数")        if not 0 <= local_port <= 65535:            raise ValueError("本机端口范围 0~65535")        target_ip = self.var_target_ip.get().strip()        if not target_ip:            raise ValueError("目标 IP 不能为空")        try:            target_port = int(self.var_target_port.get().strip())        except ValueError:            raise ValueError("目标端口必须是整数")        if not 1 <= target_port <= 65535:            raise ValueError("目标端口范围 1~65535")        try:            interval = int(self.var_interval.get().strip() or "1000")        except ValueError:            raise ValueError("发送间隔必须是整数毫秒")        if interval < 1:            interval = 1        return local_ip, local_port, target_ip, target_port, interval    def log(self, msg):        self.txt_log.insert("end", time.strftime("%H:%M:%S ") + msg + "\n")        self.txt_log.see("end")        # 简单限制日志长度        try:            line_count = int(self.txt_log.index("end-1c").split(".")[0])            if line_count > 2000:                self.txt_log.delete("1.0", "500.0")        except Exception:            pass    def clear_log(self):        self.txt_log.delete("1.0", "end")    def send_single_udp(self, payload, local_ip, local_port, target_ip, target_port):        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)        try:            sock.bind((local_ip, local_port))            sock.sendto(payload, (target_ip, target_port))        finally:            sock.close()    def on_send(self):        # 正在持续发送时，点击则停止        if self.thread is not None and self.thread.is_alive():            self.stop_event.set()            self.btn_send.config(state="disabled", text="停止中...")            return        try:            local_ip, local_port, target_ip, target_port, interval = self.get_net_config()            template = self.txt_template.get("1.0", "end-1c")            parts = compile_template(template)            if not parts:                raise ValueError("报文为空或没有有效十六进制内容")            mode = self.var_mode.get()            self.sent_count = 0            self.stop_event.clear()            if self.var_continuous.get():                # 持续发送                self.btn_send.config(text="停止发送")                self.thread = threading.Thread(                    target=self.sender_loop,                    args=(                        parts,                        local_ip,                        local_port,                        target_ip,                        target_port,                        interval,                        mode,                    ),                    daemon=True,                )                self.thread.start()            else:                # 发送一次                payload = build_payload(parts, mode, self.counters)                self.send_single_udp(payload, local_ip, local_port, target_ip, target_port)                self.sent_count = 1                self.status_var.set(f"已发送 1 包，共 {len(payload)} 字节")                self.log(f"发送 {len(payload)} 字节: {payload.hex(' ').upper()}")        except Exception as e:            self.stop_event.set()            self.btn_send.config(state="normal", text="发送")            messagebox.showerror("错误", str(e))    def sender_loop(self, parts, local_ip, local_port, target_ip, target_port, interval, mode):        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)        try:            sock.bind((local_ip, local_port))        except Exception as e:            self.root.after(0, lambda e=e: messagebox.showerror("绑定失败", str(e)))            self.root.after(0, self.finish_sending)            sock.close()            return        try:            while not self.stop_event.is_set():                try:                    payload = build_payload(parts, mode, self.counters)                    sock.sendto(payload, (target_ip, target_port))                    self.sent_count += 1                    if self.sent_count == 1 or self.sent_count % 10 == 0:                        self.root.after(                            0,                            lambda cnt=self.sent_count, ln=len(payload):                            self.status_var.set(f"持续发送中：已发送 {cnt} 包，最后 {ln} 字节")                        )                except Exception as e:                    self.root.after(0, lambda e=e: self.log(f"发送失败: {e}"))                    break                self.stop_event.wait(interval / 1000.0)        finally:            sock.close()            self.root.after(0, self.finish_sending)    def finish_sending(self):        self.thread = None        self.btn_send.config(state="normal", text="发送")        self.status_var.set(f"已停止，共发送 {self.sent_count} 包")    def on_close(self):        if self.thread is not None and self.thread.is_alive():            self.stop_event.set()        self.save_settings()        self.root.destroy()if __name__ == "__main__":    root = tk.Tk()    app = UdpHexSenderApp(root)    root.mainloop()